const verification = $('Get Verification').item.json[0];
const dniFrontBinary = $('Get DNI Front').item.binary.data;
const dniBackBinary = $('Get DNI Back').item.binary.data;
const lifeProofBinary = $('Get Life Proof').item.binary.data;

// Convert binary to base64
const dniFrontBase64 = dniFrontBinary.data;
const dniBackBase64 = dniBackBinary.data;
const lifeProofBase64 = lifeProofBinary.data;

// Get MIME types
const dniFrontMime = dniFrontBinary.mimeType || 'image/jpeg';
const dniBackMime = dniBackBinary.mimeType || 'image/jpeg';
const lifeProofMime = lifeProofBinary.mimeType || 'video/webm';

return [{
  json: {
    verification_id: verification.id,
    unique_code: verification.unique_code,
    first_name: verification.first_name,
    last_name: verification.last_name,
    dni: verification.dni,
    email: verification.email,
    card_last_four: verification.card_last_four,
    dni_front_base64: `data:${dniFrontMime};base64,${dniFrontBase64}`,
    dni_back_base64: `data:${dniBackMime};base64,${dniBackBase64}`,
    life_proof_base64: `data:${lifeProofMime};base64,${lifeProofBase64}`
  }
}];

